---
plugins {
    id "java"
}

repositories {
    mavenCentral()
}

dependencies {
    testImplementation platform("org.junit:junit-bom:5.10.0")
    testImplementation "org.junit.jupiter:junit-jupiter"
    testImplementation "org.assertj:assertj-core:3.25.1"
}

test {
    useJUnitPlatform()

    testLogging {
        exceptionFormat = "full"
        showStandardStreams = true
        events = ["passed", "failed", "skipped"]
    }
}

input.command:
TMP=$STACK_WORKDIR/opencode-probe-v2/tmp/mazy-mice/opencode
mkdir -p "$TMP"
SRC=$STACK_WORKDIR/scratch/octmp.noindex/oc-mazy-mice/mazy-mice/src/main/java/MazeGenerator.java
cat > "$TMP/MazeDemo.java" <<'EOF'
public class MazeDemo {
    public static void main(String[] args) {
        MazeGenerator g = new MazeGenerator();
        char[][] m = g.generatePerfectMaze(5, 5, 42);
        for (char[] row : m) System.out.println(new String(row));
    }
}
EOF
javac -d "$TMP" "$SRC" "$TMP/MazeDemo.java" && java -cp "$TMP" MazeDemo
